function setTab(){if(tab!=='build'){tool='inspect';updateTool();}document.body.classList.remove('city-only');$('exit-city').hidden=true;$('drawer').hidden=false;document.body.dataset.panel=tab;$('panel-title').textContent=({build:'СТРОИТЕЛЬСТВО',people:'ЖИТЕЛИ',tech:'ИССЛЕДОВАНИЯ',balance:'БАЛАНС РЕСУРСОВ',log:'СВОДКА',depth:'ПОСЕЛЕНИЯ И ТОННЕЛИ',room:'ПОМЕЩЕНИЕ'})[tab];document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-expanded',String(b.dataset.tab===tab));});renderPanel();}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(tab===b.dataset.tab&&!$('drawer').hidden){closePanel();return;}tab=b.dataset.tab;setTab();});$('close-panel').onclick=()=>{closePanel();document.querySelector(`[data-tab="${tab==='room'?'build':tab}"]`)?.focus();};$('inspect-tool').onclick=()=>{tool='inspect';selectedRoom=null;updateTool();$('hint').textContent='Нажми на комнату или жителя';};function cityMode(on){closePanel();document.body.classList.toggle('city-only',on);$('exit-city').hidden=!on;$('mini-world').hidden=on;$('mini-legend').hidden=on;$('mini-toggle').textContent='ОБЩИЙ ПЛАН ▾';if(!on)renderMiniMap();requestAnimationFrame(resize);}$('city-mode').onclick=()=>cityMode(true);$('exit-city').onclick=()=>cityMode(false);$('open-saves').onclick=()=>$('save-menu').showModal();$('close-saves').onclick=()=>$('save-menu').close();window.addEventListener('keydown',e=>{if(e.key==='Escape'){closePanel();if(document.body.classList.contains('city-only'))cityMode(false);}});if(typeof ResizeObserver!=='undefined')new ResizeObserver(resize).observe(canvas);
document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=+b.dataset.speed;paused=false;document.querySelectorAll('[data-speed]').forEach(a=>a.classList.toggle('active',a===b));ui();});$('pause').onclick=()=>{paused=!paused;ui();};$('plus').onclick=()=>zoom(1.25);$('minus').onclick=()=>zoom(.8);$('center').onclick=()=>center();$('overview').onclick=()=>center(true);$('all-districts').onclick=()=>{tool='inspect';selectedRoom=null;selected=null;closePanel();cam.empire=true;updateTool();ui();};$('mini-toggle').onclick=()=>cityMode(true);$('mini-world').onclick=e=>{let r=$('mini-world').getBoundingClientRect(),id=campaignHit(campaign,e.clientX-r.left,e.clientY-r.top,r.width,r.height);if(id!==null)goBunker(id);};$('map-districts').onclick=()=>{tab='depth';setTab();};$('back-district').onclick=()=>{if(districtHistory.length){let id=districtHistory.pop();campaign.active=id;s=activeBunker(campaign).world;center();ui();}};$('help').onclick=()=>$('guide').showModal();$('close-guide').onclick=()=>$('guide').close();
async function save(manual=false){try{await saveWorld(campaign);$('save-status').textContent='Сохранено · '+new Date().toLocaleTimeString('ru');if(manual)toast('Мир сохранён в этом браузере');}catch(e){toast('Сохранение недоступно. Скачай файл мира кнопкой ↓ Файл.');}}
$('save').onclick=()=>save(true);$('load').onclick=async()=>{try{let loaded=await loadWorld();if(!loaded){toast('Сохранение пока отсутствует');return;}campaign=loaded;s=activeBunker(campaign).world;selected=null;selectedRoom=null;districtHistory=[];center();ui();toast('Мир восстановлен');$('save-menu').close();}catch{toast('Не удалось загрузить сохранение');}};$('new').onclick=()=>{if(confirm('Начать новый мир? Текущее автосохранение будет заменено. Сначала скачай файл, если хочешь его оставить.')){campaign=createCampaign();s=activeBunker(campaign).world;selected=null;selectedRoom=null;districtHistory=[];center();ui();save();$('save-menu').close();}};$('export').onclick=()=>{let a=document.createElement('a'),url=URL.createObjectURL(new Blob([serializeCampaign(campaign)],{type:'application/json'}));a.href=url;a.download='LAST_CITY_world.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error();campaign=await prepareLoadedCampaign(restoreCampaign(await f.text()));s=activeBunker(campaign).world;selected=null;selectedRoom=null;districtHistory=[];center();ui();await save();toast('Мир импортирован');$('save-menu').close();}catch{toast('Файл повреждён или несовместим с этой версией');}e.target.value='';};
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON'].includes(e.target.tagName)){e.preventDefault();paused=!paused;ui();}});window.addEventListener('resize',resize);setInterval(()=>save(),20000);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();last=0;});
resize();center();renderPanel();ui();try{let loaded=await loadWorld();if(loaded){campaign=loaded;s=activeBunker(campaign).world;center();ui();await save();toast('Продолжаем сохранённый мир');}else $('guide').showModal();}catch{$('guide').showModal();}
function frame(now){let dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(!paused&&!document.hidden&&!$('guide').open){animationTime+=dt;let remain=dt*speed;while(remain>0){let chunk=Math.min(.2,remain);stepCampaign(campaign,chunk);s=activeBunker(campaign).world;remain-=chunk;}}if(cam.empire)drawCampaignOverview(ctx,campaign,width,height);else {draw(ctx,s,cam,width,height,selected,tool,animationTime,selectedRoom);drawTunnelWork(ctx,s,cam,tunnelSite,campaign.projects.find(p=>p.from===campaign.active),animationTime);drawVisualTunnel();}uiTime+=dt;if(uiTime>.7){ui();uiTime=0;}requestAnimationFrame(frame);}requestAnimationFrame(frame);

function focusRoom(c){cam.all=false;let old=s.activeDistrict||0,next=viewDistrictOf(c.x,c.y);if(old!==next)districtHistory.push(old);s.activeDistrict=next;cam.z=DEFAULT_ROOM_ZOOM;cam.x=width/2-(c.x+.5)*TW*cam.z;cam.y=height/2-(c.y+.5)*TH*cam.z;selectedRoom={x:c.x,y:c.y};selected=null;tool='inspect';tab='room';setTab();}
function renderBalance(panel){let cap=capacity(s),metrics=s.metrics;let intro=document.createElement('div');intro.className='detail';intro.innerHTML='<b>Как живёт бункер</b><p>Каждая строка — реальная комната. Нажми, чтобы увидеть её расход, выработку и причину остановки.</p><small>Залежь → буровая → топливо → генератор → энергия.<br>Водоносный слой → насос → питьевая вода → жители и ферма → пища.<br>Металл → мастерская → инструменты → раскопки.<br>Каждый живой житель расходует 0,02 пищи, 0,0083 воды и 0,08 энергии в секунду. Эти расходы входят в общий баланс.</small>';panel.append(intro);for(let k of STOCKS){let d=document.createElement('div');d.className='balance-stock';let net=metrics?.net[k]||0,seconds=reserveTime(s.resources[k],-net);d.innerHTML=`<b>${RESOURCE_NAMES[k]} · ${Math.floor(s.resources[k])} / ${cap}</b>${meter(s.resources[k],cap)}<small>Производство ${rate(metrics?.production[k]||0)} · расход ${rate(metrics?.consumption[k]||0)}<br>Баланс ${rate(net)}${net<-.005?' · запас на '+duration(seconds):''}</small>`;panel.append(d);}let d=document.createElement('div');d.className='detail';d.innerHTML=`<b>Подземная вода: ${Math.floor(s.resources.groundwater)} л</b>${meter(s.resources.groundwater,s.groundwaterMax,'#78ddef')}<small>Откачка ${(metrics?.groundwaterUse||0).toFixed(2)} л/с · ${duration(reserveTime(s.resources.groundwater,metrics?.groundwaterUse||0))}<br>Это общий конечный водоносный слой. Разведай и раскопай участок с подземным озером: он добавит 1000 л. Очищенная вода хранится отдельно.</small>`;panel.append(d);for(let c of s.cells.filter(c=>c.building&&!['home','storage','corridor','stairs'].includes(c.building))){let m=roomReport(s,c),b=document.createElement('button');b.className='flow-room';b.innerHTML=`${BUILD[c.building].name} <small>${m.status} · ${Math.round(m.utilization*100)}%${m.reason?' · '+m.reason:''}</small>`;b.onclick=()=>focusRoom(c);panel.append(b);}let n=document.createElement('p');n.className='note';n.textContent='Время запаса — прогноз по текущему балансу в секундах симуляции; новые комнаты, работники и технологии изменят его. Запасы отдельные для этого бункера, ёмкость указана для каждого ресурса отдельно. При паузе показан последний рабочий шаг.';panel.append(n);}
function renderRoom(panel){let c=selectedRoom?s.cells[selectedRoom.y*W+selectedRoom.x]:null;if(!c){tab='build';renderPanel();return;}let b=c.building,m=roomReport(s,c),data=barData(s,c),passive=['home','storage','stairs','corridor'].includes(b),card=document.createElement('div');card.className='room-card';card.innerHTML=`<div class="room-heading">${roomIcon(b||'inspect')}<div><small>${activeBunker(campaign).name} · КОМНАТА ${c.x-VIEW_DISTRICTS[viewDistrictOf(c.x,c.y)].x+1}:${c.y-VIEW_DISTRICTS[viewDistrictOf(c.x,c.y)].y+1}</small><h3>${b?BUILD[b].name:'Пустое помещение'}</h3></div></div><div class="room-state ${m.utilization>0||passive?'online':''}">● ${m.status}</div><p class="stop-reason">${m.reason}</p>`;panel.append(card);if(c.feature){let note=document.createElement('p');note.className='note';note.textContent=depositDescription(c);note.style.color=DEPOSITS[c.feature]?.color||'';card.append(note);}let alert=roomAlert(s,c);if(alert){let banner=document.createElement('div');banner.className='room-alert';banner.textContent=alert.kind==='exhausted'?(b==='mine'?'Руда исчерпана. Разбери шахту и построй следующую на новой рудной залежи.':'Залежь исчерпана. Разбери буровую и построй следующую на новой топливной залежи.'):'Заполнен запас: '+alert.resources.map(k=>RESOURCE_NAMES[k]).join(', ')+'. Построй дополнительный склад или расходуй ресурсы.';card.append(banner);}if(b&&!passive)renderRoomControls(card,c);renderSupply(card,c);
let job=s.jobs.find(j=>j.x===c.x&&j.y===c.y);if(job){let d=document.createElement('div');d.className='maintenance';d.innerHTML=`<b>${job.type==='dismantle'?'Разборка':job.type==='dig'?'Раскопки':'Строительство'} · ${Math.round(job.progress/job.total*100)}%</b>${meter(job.progress,job.total,'#f0ba81')}<small>Назначенные строители: ${s.people.filter(p=>p.job===job.id).length}${job.blocked?'<br>'+job.blocked:''}</small>`;if(job.type==='dismantle'){let cancel=document.createElement('button');cancel.textContent='Отменить разборку';cancel.onclick=()=>{toast(command(s,'cancelDismantle',c.x,c.y)||'Разборка отменена');ui();};d.append(cancel);}card.append(d);}else if(b){let refund=salvage(b),error=dismantleCheck(s,c),d=document.createElement('div');d.className='maintenance';d.innerHTML=`<b>Возврат при разборке</b><small>${refund.material} материалов · ${refund.metal} металла<br>Оборудование остановится сразу. Разборку выполняет строитель; помещение и оставшаяся залежь сохраняются.${error?'<br><span class="stop-reason">'+error+'</span>':''}</small>`;let button=document.createElement('button');button.textContent='Разобрать оборудование';button.disabled=!!error;button.onclick=()=>{if(confirm(`Разобрать «${BUILD[b].name}»? Комната перестанет работать. После разборки вернутся ${refund.material} материалов и ${refund.metal} металла.`)){toast(command(s,'dismantle',c.x,c.y)||'Разборка назначена');ui();}};d.append(button);card.append(d);}
if(b){if(!passive){let d=document.createElement('div');d.className='balance-stock';d.innerHTML=`<b>Мощность: ${Math.round(m.utilization*100)}%</b>${meter(m.utilization,1)}<small>${m.automatic?'Автоматика':m.staff.length?'Оператор: '+m.staff.map(id=>s.people.find(p=>p.id===id)?.name).join(', '):'Оператор не на месте'}<br>Энергия: ${(m.actualInput.energy||0).toFixed(2)} / ${m.power.toFixed(2)} в секунду</small>`;card.append(d);for(let [title,rates,actual] of [['Потребляет',m.input,m.actualInput],['Производит',m.output,m.actualOutput]]){let rows=Object.entries(rates).map(([k,v])=>`<div class="room-facts"><span>${k==='oreDeposit'?'Из рудной залежи':k==='deposit'?'Из залежи':RESOURCE_NAMES[k]}</span><b>${(actual[k]||0).toFixed(2)} / ${v.toFixed(2)} /с</b></div>`).join('');if(rows){let d=document.createElement('div');d.innerHTML=`<h4>${title} · факт / максимум</h4>${rows}`;card.append(d);}}}
if(!['corridor','stairs'].includes(b)){let d=document.createElement('div');d.className='balance-stock';d.innerHTML=`<b>${data.label}: ${Math.floor(data.value)} / ${Math.floor(data.max)}</b>${meter(data.value,data.max,data.color)}`;card.append(d);}
let note={mine:'Добывает руду из конечной залежи. Для превращения в металл нужна плавильня. Энергия и оператор либо автоматика обязательны.',smelter:'Каждые 2 кг руды дают 1 кг металла. Требуются топливо и энергия; сырьё доставляется автоматически.',home:`8 мест для отдыха. Всего жилья: ${s.people.filter(p=>p.health>0).length} жителей / ${housingCapacity(s)} мест. Полоса показывает людей здесь сейчас, а не закреплённые койки.`,storage:'Запасы складов этого бункера. Этот склад добавляет 600 к ёмкости каждого ресурса. Верхняя полоса — среднее заполнение восьми запасов. Красное мигание означает, что хотя бы один ресурс достиг ёмкости.',corridor:'Проход соединяет комнаты; оператор не нужен.',stairs:'Соединяет уровни; оператор не нужен.',generator:'Генератор превращает топливо в энергию. При полном запасе мощность снижается до потребности бункера.',drill:'Добывает топливо из конечной залежи под этой комнатой. Нужны энергия и оператор либо автоматика.',water:'Насос очищает воду из общего конечного водоносного слоя. Для пополнения разведай и раскопай подземное озеро.',farm:'Вода и энергия превращаются в пищу. Полный пищевой запас останавливает производство.',quarry:'Раскопанная порода перерабатывается в стройматериалы.',workshop:'Металл превращается в инструменты для раскопок.',lab:'Из металла и энергии создаёт научные данные.',med:'Расходует воду и энергию только при наличии раненых.',vent:'Активная вентиляция уменьшает последствия газовых карманов.',radio:'180 секунд работы привлекают 3 выживших; при очереди 30 человек работа останавливается.'}[b];let n=document.createElement('p');n.className='note';n.textContent=note;card.append(n);
if(['drill','water','generator'].includes(b)){let stock=b==='drill'?c.fuelReserve:b==='water'?s.resources.groundwater:s.resources.fuel,draw=b==='drill'?m.actualInput.deposit:b==='water'?s.metrics?.groundwaterUse:Math.max(0,-(s.metrics?.net.fuel||0));let n=document.createElement('p');n.className='note';n.textContent='При текущем расходе: '+duration(reserveTime(stock,draw||0))+(b==='generator'?' (с учётом добычи топлива)':'');card.append(n);}
if(b==='storage')for(let k of STOCKS){let d=document.createElement('div');d.className='balance-stock';d.innerHTML=`${RESOURCE_NAMES[k]} <b>${Math.floor(s.resources[k])} / ${capacity(s)}</b>${meter(s.resources[k],capacity(s))}`;card.append(d);}
if(b==='radio'){let d=document.createElement('div');d.className='balance-stock';d.innerHTML=`Сигнал ${Math.floor(s.signalTime)} / 180 с${meter(s.signalTime,180)}`;card.append(d);}}
let heading=document.createElement('h4');heading.textContent='В помещении';card.append(heading);for(let p of s.people.filter(p=>p.health>0&&Math.round(p.x)===c.x&&Math.round(p.y)===c.y)){let button=document.createElement('button');button.className='person';button.innerHTML=`<span class="mini-portrait">${portrait(p)}</span>${p.name}<small>${p.task}</small>`;button.onclick=()=>{selected=p.id;selectedRoom=null;peopleFilter='all';tab='people';setTab();};card.append(button);}let back=document.createElement('button');back.className='room-back';back.textContent='← Строительное меню';back.onclick=()=>{tab='build';setTab();};panel.append(back);}

function renderRoomControls(card,c){let d=document.createElement('div');d.className='room-controls';let running=c.enabled!==false,toggle=document.createElement('button');toggle.className=running?'':'active';toggle.textContent=running?'Ⅱ Остановить комнату':'▶ Включить комнату';toggle.onclick=()=>{toast(setRoomEnabled(s,c,!running)||(!running?'Комната включена':'Комната остановлена, оператор освобождён'));ui();};d.append(toggle);let m=roomReport(s,c);if(!m.automatic){let label=document.createElement('label');label.textContent='Закреплённый оператор';let select=document.createElement('select');select.innerHTML='<option value="">Автоматический выбор</option>';let candidates=operatorCandidates(s,c),assigned=s.people.find(p=>p.id===c.preferredOperator);if(assigned&&!candidates.includes(assigned))candidates.unshift(assigned);for(let p of candidates){let opt=document.createElement('option');opt.value=p.id;opt.textContent=p.name+' · энергия '+Math.floor(residentEnergy(p))+'%'+(p.task==='Отдых'?' · отдыхает':'');opt.selected=p.id===c.preferredOperator;select.append(opt);}select.onchange=e=>{toast(assignOperator(s,c,e.target.value===''?null:+e.target.value)||'Назначение обновлено');ui();};label.append(select);d.append(label);let note=document.createElement('small');note.textContent='Доступны свободные жители и текущий оператор. Закрепление сохраняется во время отдыха; комнату может временно обслужить другой житель.';d.append(note);}
if(['generator','water','farm','quarry','workshop','lab','drill','mine','smelter'].includes(c.building)){let label=document.createElement('label');label.textContent=c.building==='generator'?'Поддерживать запас энергии':'Производить до запаса';let row=document.createElement('div');row.className='target-row';let input=document.createElement('input');input.type='number';input.min='1';input.max=c.building==='lab'?1000:capacity(s);input.value=c.productionTarget||'';input.placeholder='Весь склад';input.setAttribute('aria-label','Целевой запас');let apply=document.createElement('button');apply.textContent='Задать';apply.onclick=()=>{let value=input.value.trim()===''?null:Number(input.value);toast(setProductionTarget(s,c,value)||'Целевой запас обновлён');ui();renderPanel();};row.append(input,apply);label.append(row);d.append(label);let note=document.createElement('small');note.textContent='Общий запас ресурса. Пустое поле снимает ограничение. Если запас уменьшится, производство возобновится при наличии сырья, энергии и работника.';d.append(note);}card.append(d);}
function renderQueue(panel){let block=document.createElement('div');block.className='queue';block.innerHTML=`<h3>Очередь работ · ${s.jobs.length}</h3><small>Приоритет меняет порядок и освобождает строителей от следующих заданий. Выполненный прогресс сохраняется.</small>`;if(!s.jobs.length){let n=document.createElement('p');n.className='note';n.textContent='Сначала выбери раскопки или помещение ниже.';block.append(n);}for(let [i,j] of s.jobs.entries()){let refund=cancelRefund(j),row=document.createElement('div');row.className='queue-job';let who=s.people.find(p=>p.health>0&&p.job===j.id),name=j.type==='dig'?'Раскопки':j.type==='dismantle'?'Разборка: '+BUILD[j.building].name:BUILD[j.building].name;row.innerHTML=`<b>${i+1}. ${name}</b><small>Район ${viewDistrictOf(j.x,j.y)+1} · ${j.x-VIEW_DISTRICTS[viewDistrictOf(j.x,j.y)].x+1}:${j.y-VIEW_DISTRICTS[viewDistrictOf(j.x,j.y)].y+1} · ${Math.round(j.progress/j.total*100)}% · ${who?who.name:'ожидает строителя'}${j.blocked?'<br>'+j.blocked:''}</small>${meter(j.progress,j.total,'#efc18a')}<small>При отмене: ${Object.entries(refund).filter(([,v])=>v>0).map(([k,v])=>v+' '+RESOURCE_NAMES[k].toLowerCase()).join(', ')||'без возврата'}<br>Уже выполненная работа расходует часть стоимости.</small>`;let actions=document.createElement('div');actions.className='queue-actions';for(let [action,text] of [['first','↑ В первую очередь'],['locate','На карте'],['cancel','Отменить']]){let b=document.createElement('button');b.textContent=text;b.disabled=action==='first'&&i===0;b.onclick=()=>{if(action==='locate'){s.activeDistrict=viewDistrictOf(j.x,j.y);cam.x=width/2-(j.x+.5)*TW*cam.z;cam.y=height/2-(j.y+.5)*TH*cam.z;closePanel();return;}toast(jobAction(s,j.id,action)||(action==='first'?'Приоритет повышен':'Задание отменено'));ui();};actions.append(b);}row.append(actions);block.append(row);}panel.append(block);}
function renderWarnings(){let warnings=bunkerWarnings(s),b=$('warning-banner');if(!warnings.length){b.hidden=true;return;}let w=warnings[0];b.hidden=false;b.textContent='⚠ '+w.text+(warnings.length>1?' · ещё '+(warnings.length-1):'')+' →';b.onclick=()=>{let source=w.key==='fuel'?s.cells.find(c=>c.seen&&c.feature==='fuel'&&c.fuelReserve>0):w.key==='groundwater'?s.cells.find(c=>c.seen&&c.type==='rock'&&c.feature==='lake'):null;if(source){s.activeDistrict=viewDistrictOf(source.x,source.y);cam.x=width/2-(source.x+.5)*TW*cam.z;cam.y=height/2-(source.y+.5)*TH*cam.z;closePanel();toast(source.type==='rock'?'Источник найден: сначала раскопай участок':'Источник найден: проверь или построй оборудование');}else{tab='balance';setTab();}};}

function renderSupply(card,c){let k=supplyInputs[c.building];if(!k)return;let d=document.createElement('div');d.className='supply-card';let max=supplyCapacity(s,c),stock=c.supply?.[k]||0,route=supplyRoute(s,c),m=roomReport(s,c),draw=m.actualInput[k]||0;d.innerHTML=`<h4>Автоматическое снабжение</h4><b>${RESOURCE_NAMES[k]} в комнате: ${stock.toFixed(2)} / ${max.toFixed(2)}</b>${meter(stock,max,'#85e0d4')}<small>Рабочий запас на ${s.unlocks.includes('freight')?60:30} секунд полной мощности.<br>При текущем расходе: ${duration(reserveTime(stock,draw))}<br>Доставка: ${(c.deliveryRates?.[k]||0).toFixed(2)} /с · ${route?'путь '+route.route.length+' помещений':'нет пути к складу'}<br>Свободно в общих запасах: ${freeStock(s,k).toFixed(1)}<br>Запас комнаты входит в число ресурсов сверху. Доставка и пополнение работают автоматически.</small>`;if(c.building==='smelter'){let n=document.createElement('small');n.textContent='Топливо в плавильне: '+(c.supply?.fuel||0).toFixed(2)+' / '+supplyCapacity(s,c,'fuel').toFixed(2)+' л';d.append(n);}if(route){let b=document.createElement('button');b.textContent='Показать питающий склад';b.onclick=()=>focusRoom(route.source);d.append(b);}card.append(d);}

function renderDepth(panel){let deposits=s.cells.filter(n=>n.x<30&&n.y<20&&n.seen&&n.largeDeposit);if(deposits.length){let title=document.createElement('h4');title.textContent='Крупные месторождения';panel.append(title);for(let c of deposits){let button=document.createElement('button');button.className='person';button.style.color=DEPOSITS[c.feature].color;button.textContent=depositDescription(c)+' · '+(c.x+1)+':'+(c.y+1);button.onclick=()=>{cam.empire=false;cam.z=DEFAULT_ROOM_ZOOM;cam.x=width/2-(c.x+.5)*TW*cam.z;cam.y=height/2-(c.y+.5)*TH*cam.z;selectedRoom={x:c.x,y:c.y};tool='inspect';updateTool();closePanel();toast(depositDescription(c));};panel.append(button);}}let b=activeBunker(campaign),status=bunkerStatus(b),intro=document.createElement('div');intro.className='depth-intro';intro.innerHTML=`<small>НОВАЯ ЦИВИЛИЗАЦИЯ</small><h3>${b.name}</h3><p>30 × 20 помещений · ${status.state}<br>Исследовано ${status.known}/600<br>Жители ${s.people.filter(p=>p.health>0).length} · ёмкость ${capacity(s)}</p><small>Запасы и население отдельные. Все основанные бункеры продолжают работать.</small>`;panel.append(intro);let cards=document.createElement('div');cards.className='settlement-list';for(let colony of campaign.bunkers){let button=document.createElement('button');button.className='district-tile'+(colony.id===campaign.active?' active':'');button.innerHTML='<b>'+colony.name+'</b><small>'+bunkerStatus(colony).state+' · '+colony.world.people.filter(p=>p.health>0).length+' жителей</small>';button.onclick=()=>goBunker(colony.id);cards.append(button);}panel.append(cards);
if(!b.founded){let button=document.createElement('button');button.textContent='Отправить 5 переселенцев и модульный бункер';button.onclick=()=>{toast(foundBunker(campaign,b.id)||'Группа и груз отправлены');ui();};panel.append(button);let note=document.createElement('p');note.className='note';note.textContent='Комплект: 240 материалов, 90 металла, 120 пищи, 150 воды, 100 топлива, 15 инструментов. Модули собираются после прибытия, стоимость помещений списывается из комплекта.';panel.append(note);}else{let controls=document.createElement('div');controls.className='room-controls';let survey=document.createElement('button');survey.textContent=status.known===600?'Бункер обследован':'Обследовать весь бункер · 10 научных данных';survey.disabled=status.known===600;survey.onclick=()=>{toast(surveyBunker(campaign,b.id)||'Геологическое обследование завершено');ui();};controls.append(survey);let automatic=document.createElement('button');automatic.textContent=b.automatic?'Вернуть ручное управление':'Перевести в автономный режим';automatic.onclick=()=>{toast(setBunkerAutomatic(campaign,b.id,!b.automatic)||'Режим управления изменён');ui();};controls.append(automatic);let note=document.createElement('small');note.textContent=status.reasons.length?'Для автономности: '+status.reasons.join('; '):'Все условия выполнены. Автономность не создаёт бесплатных ресурсов.';controls.append(note);panel.append(controls);let heading=document.createElement('h4');heading.textContent='Тоннель в новый сектор';panel.append(heading);for(let [direction,label] of [['east','Вправо'],['west','Влево'],['down','Вниз'],['up','Вверх']]){let button=document.createElement('button');button.textContent=label;button.onclick=()=>launchTunnel(direction);panel.append(button);}let cost=document.createElement('p');cost.className='note';cost.textContent='Тоннель: 40 материалов, 12 металла, 2 инструмента и один строитель. Нужен доступный проход к выбранному краю.';panel.append(cost);}
for(let p of campaign.projects){let d=document.createElement('div');d.className='queue';d.innerHTML='<b>Прокладка тоннеля</b>'+meter(p.progress,p.total,'#e5c085')+'<small>'+Math.floor(p.progress)+' / '+p.total+' работы</small>';panel.append(d);}for(let t of campaign.shipments){let d=document.createElement('div');d.className='queue';d.innerHTML='<b>'+(t.kind==='found'?'Переселенцы и модули':'Грузовая тележка')+' · '+t.from+' → '+t.to+'</b>'+meter(t.total-t.remaining,t.total,'#a7dcca')+'<small>'+shipmentStatus(campaign,t)+'<br>До прибытия '+Math.ceil(t.remaining)+' с<br>'+Object.entries(t.cargo).filter(([,v])=>v>.01).map(([k,v])=>RESOURCE_NAMES[k]+': '+v.toFixed(1)).join(' · ')+'</small>';panel.append(d);}let note=document.createElement('p');note.className='note';note.textContent='Грузовые тележки автоматически пополняют дефицит пищи, воды, топлива и материалов, сохраняя резерв у отправителя. Рейс расходует 1 топлива. Электроэнергия и водоносный слой между бункерами не перевозятся.';panel.append(note);for(let line of campaign.log.slice(0,8)){let item=document.createElement('div');item.className='log-item';item.textContent=line;panel.append(item);}}
function goBunker(id){if(!campaign.bunkers.some(b=>b.id===id))return;let old=campaign.active;if(old!==id)districtHistory.push(old);campaign.active=id;s=activeBunker(campaign).world;cam.empire=false;selected=null;selectedRoom=null;tool='inspect';updateTool();closePanel();center();ui();toast(activeBunker(campaign).name);}

function goDistrict(id){goBunker(id);}

function renderDistricts(panel){let map=document.createElement('div');map.className='district-grid';for(let d of VIEW_DISTRICTS){let known=viewDistrictKnown(s,d.id),local=viewDistrictCells(s,d.id),links=viewPortals(s,d.id),rooms=local.filter(c=>c.building).length,people=s.people.filter(p=>p.health>0&&viewDistrictOf(p.x,p.y)===d.id).length,b=document.createElement('button');b.className='district-tile'+(d.id===(s.activeDistrict||0)?' active':'');b.disabled=!known;b.innerHTML='<b>'+String(d.id+1).padStart(2,'0')+' · '+d.name+'</b><small>'+d.w+' × 4 · '+(known?rooms+' комнат · '+people+' жителей<br>Переходов: '+links.length:'Неизвестная территория')+'</small>';b.onclick=()=>goDistrict(d.id);map.append(b);}panel.append(map);let exits=document.createElement('div');exits.className='district-exits';let unique=new Map();for(let link of viewPortals(s,s.activeDistrict||0)){let id=link.from===(s.activeDistrict||0)?link.to:link.from;if(!unique.has(id))unique.set(id,link);}for(let [id,link] of unique){let b=document.createElement('button');b.textContent=link.kind+' → '+VIEW_DISTRICTS[id].name;b.onclick=()=>goDistrict(id,link);exits.append(b);}panel.append(exits);let note=document.createElement('p');note.className='note';note.textContent='Переход появляется, когда рабочие раскопают обе стороны границы районов. Между уровнями нужна лестница. Нажми на зелёную табличку тоннеля на карте. Жители и снабжение используют эти же реальные проходы; остальные районы продолжают работать.';panel.append(note);}

function renderMiniMap(){let canvas=$('mini-world');if(canvas.hidden)return;let rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(rect.width<=0||rect.height<=0)return;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);let g=canvas.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);drawCampaignOverview(g,campaign,rect.width,rect.height,true);}

$('cleanup-backup').onclick=async()=>{try{let text=await cleanupBackupText();if(!text){toast('Копия до очистки пока отсутствует');return;}let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.href=url;a.download='LAST_CITY_before_bunkers234_cleanup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{toast('Не удалось прочитать резервную копию');}};

function focusTunnel(site){$('mini-world').hidden=true;$('mini-legend').hidden=true;$('mini-toggle').textContent='ОБЩИЙ ПЛАН ▸';cam.empire=false;cam.all=false;cam.z=Math.max(1.25,DEFAULT_ROOM_ZOOM);cam.x=width*.58-(site.x+.5)*TW*cam.z;cam.y=height*.48-(site.y+.5)*TH*cam.z;tool='inspect';selected=null;selectedRoom=null;closePanel();updateTool();}
function launchTunnel(direction){let project=campaign.projects.find(p=>p.from===campaign.active);if(project){focusTunnel(project.edge);paused=false;ui();return;}let site=direction?null:nextTunnelEntrance(campaign,campaign.active);if(!direction&&!site){toast('Раскопай доступное помещение у края бункера, лучше справа.');return;}let error=startTunnel(campaign,campaign.active,direction||site.direction);if(error){toast(error);return;}project=campaign.projects.find(p=>p.from===campaign.active);tunnelSite={...project.edge,direction:project.direction};focusTunnel(tunnelSite);paused=false;toast('Строитель идёт к краю бункера. Проходка начнётся после его прибытия.');ui();}
function updateTunnelControls(){let b=activeBunker(campaign),project=campaign.projects.find(p=>p.from===b.id),known=bunkerStatus(b).known;let link=[...campaign.links].reverse().find(l=>l.a===b.id&&campaign.bunkers.some(n=>n.id===l.b&&!n.founded));tunnelTarget=link?.b||null;let next=known===600?nextTunnelEntrance(campaign,b.id):null;tunnelSite=project?{...project.edge,direction:project.direction}:next;let button=$('tunnel-button'),status=$('tunnel-status');button.hidden=!b.founded;button.disabled=!project&&(known<600||!next||campaign.projects.length>0||campaign.bunkers.some(n=>n!==b&&(!n.founded||bunkerStatus(n).known<600)));button.textContent=project?'⚒ Тоннель · '+Math.floor(project.progress/project.total*100)+'%':'⚒ Тоннель';if(project){let crew=s.people.filter(p=>project.crew.includes(p.id));status.textContent=crew.some(p=>p.task==='Отдых')?'Строитель отдыхает и продолжит работу.':crew.some(p=>p.path.length||Math.round(p.x)!==project.edge.x||Math.round(p.y)!==project.edge.y)?'Строитель идёт к месту проходки…':'Рабочий роет тоннель…';}else status.textContent=tunnelTarget?'Тоннель готов. Новый бункер открыт на мини-карте.':!b.founded?'Новый сектор. Отправь переселенцев через «Поселения».':known<600?'Для тоннеля: исследовано '+known+' / 600':!next?'Нужен доступный проход к краю карты.':button.disabled?'Сначала исследуй уже открытый бункер.':'40 материалов · 12 металла · 2 инструмента';$('tunnel-enter').hidden=!tunnelTarget;if(campaign.bunkers.length>lastBunkerCount){$('mini-world').hidden=false;$('mini-legend').hidden=false;$('mini-toggle').textContent='ОБЩИЙ ПЛАН ▾';toast('Тоннель готов! Новый бункер появился на мини-карте.');}lastBunkerCount=campaign.bunkers.length;}
$('tunnel-button').onclick=()=>launchTunnel();$('tunnel-enter').onclick=()=>{if(tunnelTarget)goBunker(tunnelTarget);};
